// border-type 1/2 split and the /500 alpha ramp are the identifying constants. Position in ViewDraw2
// confirms it: the final call of the pass.
// @wasnamed DRAW_WORLD_FadeEffectJustWarped
// Draws the post-warp black fade-out over the play area, ramping alpha down over 500 ms.
// 1.14d mac: 0006293d
void __stdcall dSceneTransitionDraw() {
    if (!gdwWarpFadeExpireTime) {
      return;
    }

    DWORD dwTickCount = GetTickCount();
    if (dwTickCount > gdwWarpFadeExpireTime) {
      gdwWarpFadeExpireTime = 0;
      return;
    }

    int nTimeRemaining = gdwWarpFadeExpireTime - dwTickCount; // steer-ok: the original computes the remaining time before the border-type call
    int nYEnd = UI::Inv::ScreenSizeY - 0x2f; // steer-ok: the asm stores ScreenSizeY-0x2f to the frame before the border-type call
    int32_t nXStart = 0;
    int nXEnd = UI::ui::ScreenSizeX;
    switch (UI::Path::DRAW_GetTypeOfBorder()) {
      case 1:
        nXEnd -= UI::ui::ScreenSizeX / 2;
        break;
      case 2:
        nXStart = UI::ui::ScreenSizeX / 2;
        break;
    }

    D2gfx::D2GFX::D2GFX_DrawSolidRectAlpha(nXStart, 0, nXEnd, nYEnd, 0, nTimeRemaining * 0xff / 500);
}

// 1.14d mac: 00062a07
void __stdcall DRAW_WORLD_ClearWarpFadeTimer() {
    gdwWarpFadeExpireTime = 0;
}

// 1.14d mac: 0012b5ca
int __fastcall CUNITEVENT_DispatchCallbacks(int nClientEvent, D2UnitStrc * pOwnerUnit, D2UnitStrc * pMissile, uint32_t dwParam4) {
    if (!pOwnerUnit) {
      return 0;
    }

    int32_t dwResult = 0;
    D2CUnitEventStrc* pEvent = pOwnerUnit->uSideData.pClientSide.pCUnitEventList;
    while (pEvent) {
      D2CUnitEventStrc* pNextCallback = pEvent->pPrev;
      if (pEvent->nClientEvent == nClientEvent) {
        dwResult = pEvent->pfnCallback(nClientEvent, pOwnerUnit, pMissile, dwParam4, pEvent->dwEventData1, pEvent->dwEventData2);
      }
      pEvent = pNextCallback;
    }
    return dwResult;
}

